import json, os, glob

# Scan recent sessions
sessions_dir = '.state/sessions/history'
dirs = sorted(os.listdir(sessions_dir), key=lambda d: os.path.getmtime(os.path.join(sessions_dir, d)), reverse=True)[:40]

agent_stats = {}  # agent -> {tool_counts, total_ops, total_size, bash_cat, sessions}
for d in dirs:
    meta_path = os.path.join(sessions_dir, d, 'meta.json')
    session_path = os.path.join(sessions_dir, d, 'session.jsonl')
    if not os.path.exists(session_path):
        continue

    # Get agent
    agent = '?'
    if os.path.exists(meta_path):
        try:
            with open(meta_path) as f:
                meta = json.load(f)
            agent = meta.get('agent', '?')
        except:
            pass

    if agent not in agent_stats:
        agent_stats[agent] = {'tool_counts': {}, 'total_ops': 0, 'total_size': 0, 'bash_cat': 0, 'sessions': 0}

    stats = agent_stats[agent]
    stats['sessions'] += 1
    stats['total_size'] += os.path.getsize(session_path)

    with open(session_path) as f:
        for line in f:
            try:
                entry = json.loads(line)
            except:
                continue
            stats['total_ops'] += 1
            if entry.get('role') == 'assistant' and isinstance(entry.get('content'), list):
                for block in entry['content']:
                    if isinstance(block, dict) and block.get('type') == 'toolCall':
                        name = block.get('name', '?')
                        stats['tool_counts'][name] = stats['tool_counts'].get(name, 0) + 1
                        if name == 'bash':
                            cmd = block.get('arguments', {}).get('command', '')
                            if 'cat ' in cmd and ('grep' not in cmd or cmd.index('cat ') < cmd.index('grep')):
                                stats['bash_cat'] += 1

# Print summary
for agent, stats in sorted(agent_stats.items(), key=lambda x: -x[1]['total_size']):
    print(f'\n{agent}: {stats[\"sessions\"]} sessions, {stats[\"total_ops\"]} lines, {stats[\"total_size\"]//1024}KB')
    tools = stats['tool_counts']
    total_tools = sum(tools.values())
    print(f'  Total tool calls: {total_tools}')
    for t, c in sorted(tools.items(), key=lambda x:-x[1]):
        pct = c*100//max(total_tools,1)
        print(f'    {t}: {c} ({pct}%)')
    if stats['bash_cat'] > 0:
        cat_rate = stats['bash_cat']*100//max(tools.get('bash',1),1)
        print(f'  Bash-cat: {stats[\"bash_cat\"]} ({cat_rate}% of bash calls)')
"

