import json

with open('.state/sessions/history/s_1774253412433_2/session.jsonl') as f:
    lines = f.readlines()

# Extract tool results and their sizes
tool_results = []
for line in lines:
    entry = json.loads(line)
    if entry.get('role') == 'toolResult':
        name = entry.get('toolName', '?')
        content = entry.get('content', [])
        size = sum(len(b.get('text', '')) for b in content if isinstance(b, dict))
        tool_id = entry.get('toolCallId', '?')
        tool_results.append((name, size, tool_id))

# Sort by size
print('Largest tool results:')
for name, size, tid in sorted(tool_results, key=lambda x:-x[1])[:15]:
    print(f'  {name}: {size//1024}KB ({tid[:20]})')

# Also find what commands produced these large results
for line in lines:
    entry = json.loads(line)
    if entry.get('role') == 'assistant' and isinstance(entry.get('content'), list):
        for block in entry['content']:
            if isinstance(block, dict) and block.get('type') == 'toolCall':
                tid = block.get('id', '')
                # Check if this is one of the big ones
                for name, size, rtid in tool_results:
                    if tid == rtid and size > 5000:
                        args = block.get('arguments', {})
                        if block['name'] == 'bash':
                            print(f'  -> bash({args.get(\"command\", \"\")[:150]})')
                        elif block['name'] == 'read':
                            print(f'  -> read({args.get(\"path\", \"\")})')
                        elif block['name'] == 'workflow':
                            print(f'  -> workflow({args.get(\"name\", \"\")} / {str(args.get(\"task\", \"\"))[:100]})')
                        else:
                            print(f'  -> {block[\"name\"]}({str(args)[:120]})')
"

